<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { ArrowLeft, ChevronDown, Pencil, Plus, Trash2, ArrowUp, ArrowDown } from 'lucide-vue-next'
import WorkspaceStickyStack from '../components/WorkspaceStickyStack.vue'
import WorkspaceTabs from '../components/WorkspaceTabs.vue'
import StatusBadge from '../components/StatusBadge.vue'
import JalaliDatePicker from '../components/JalaliDatePicker.vue'
import OrderItemConfigurator from '../components/OrderItemConfigurator.vue'
import DocumentMetadataPanel from '../components/DocumentMetadataPanel.vue'
import type { OrderRecord, OrderPayload, OrderItemPayload } from '../api/orders'
import { ordersApi } from '../api/orders'
import type { CurrencyUnit } from '../utils/currency'
import { formatMoney, formatMoneyInput, parseMoneyInput } from '../utils/currency'
import { formatDateTime } from '../utils/date'
import OrderProductionPanel from './OrderProductionPanel.vue'
import OrderPaymentsPanel from './OrderPaymentsPanel.vue'
import OrderInvoicePanel from './OrderInvoicePanel.vue'
const props=defineProps<{order:OrderRecord;currencyUnit:CurrencyUnit;customers:any[];services:any[];materials:any[]}>();const emit=defineEmits<{back:[];notify:[message:string];saved:[order:OrderRecord]}>()
const tab=ref('Overview');const customerId=ref('');const promisedAt=ref<string|null>(null);const priority=ref('Normal');const notes=ref('');const discountText=ref('');const editorOpen=ref(false);const editingItem=ref<any|null>(null);const saving=ref(false)
const tabs=['Overview','Items','Production','Payments','Invoices','Files','History'];const customer=computed(()=>props.customers.find(c=>c.id===customerId.value));
watch(()=>props.order,(o)=>{customerId.value=o.customerId||'';promisedAt.value=o.promisedAt;priority.value=o.priority;notes.value=o.notes;discountText.value=formatMoneyInput(o.discountRial,props.currencyUnit)},{immediate:true})
function tone(v:string){return v==='Confirmed'||v==='In Production'?'blue':v==='Closed'||v==='Delivered'||v==='Paid'||v==='Ready'?'green':v==='Cancelled'?'red':v==='Partially Paid'?'amber':'slate'}
function money(v:number){return formatMoney(v,props.currencyUnit)}
function payload():OrderPayload{return{customerId:customerId.value,promisedAt:promisedAt.value,priority:priority.value,notes:notes.value,discountRial:parseMoneyInput(discountText.value,props.currencyUnit)||0}}
async function saveMetadata(){saving.value=true;try{const result=await ordersApi.update(props.order.id,payload());emit('saved',result);emit('notify','Order details saved')}catch(e){emit('notify',String(e))}finally{saving.value=false}}
async function updateDiscount(){saving.value=true;try{const amount=parseMoneyInput(discountText.value,props.currencyUnit);if(amount===null)throw new Error('Enter a valid discount');const result=await ordersApi.discount(props.order.id,amount);emit('saved',result);emit('notify','Discount applied')}catch(e){emit('notify',String(e))}finally{saving.value=false}}
async function configured(input:OrderItemPayload){saving.value=true;const replacing=Boolean(editingItem.value);try{const result=replacing?await ordersApi.replaceItem(props.order.id,editingItem.value.id,input):await ordersApi.addItem(props.order.id,input);emit('saved',result);editorOpen.value=false;editingItem.value=null;emit('notify',replacing?'Item replaced':'Item added')}catch(e){emit('notify',String(e))}finally{saving.value=false}}
async function remove(item:any){try{emit('saved',await ordersApi.removeItem(props.order.id,item.id));emit('notify','Item removed')}catch(e){emit('notify',String(e))}}
async function move(item:any,delta:number){const items=[...props.order.items].sort((a,b)=>a.position-b.position);const index=items.findIndex(i=>i.id===item.id);const next=index+delta;if(next<0||next>=items.length)return;[items[index],items[next]]=[items[next],items[index]];try{emit('saved',await ordersApi.reorderItems(props.order.id,items.map(i=>i.id)))}catch(e){emit('notify',String(e))}}
async function changeCommercial(e:Event){try{emit('saved',await ordersApi.commercialStatus(props.order.id,(e.target as HTMLSelectElement).value));emit('notify','Commercial status updated')}catch(err){emit('notify',String(err))}}
async function changeFulfillment(e:Event){try{emit('saved',await ordersApi.fulfillmentStatus(props.order.id,(e.target as HTMLSelectElement).value));emit('notify','Fulfillment status updated')}catch(err){emit('notify',String(err))}}
function snapshot(item:any,key:string){try{return JSON.parse(item[key]||'[]')}catch{return[]}}
</script>
<template><div class="order-workspace"><WorkspaceStickyStack :flush="true"><header class="order-workspace-header"><button class="back-button" @click="emit('back')"><ArrowLeft :size="16"/>Orders</button><div class="order-heading-copy"><p class="eyebrow">Sales / Order workspace</p><div class="order-title-row"><h1>{{ order.orderNumber }}</h1><StatusBadge :label="order.commercialStatus" :tone="tone(order.commercialStatus)"/></div><p class="heading-description">{{ order.customerName||'Walk-in customer' }} · {{ order.items.length }} line items</p></div><div class="order-header-actions"><span class="select-control"><select :value="order.commercialStatus" aria-label="Commercial status" @change="changeCommercial"><option>Draft</option><option>Confirmed</option><option>Closed</option><option>Cancelled</option></select><ChevronDown class="select-chevron" :size="14"/></span><button class="button button-primary" :disabled="saving" @click="saveMetadata">{{ saving?'Saving…':'Save order' }}</button></div></header><section class="order-meta-strip"><div class="order-meta-cell"><span class="meta-label">Customer</span><span class="meta-value">{{ order.customerName||'Walk-in customer' }}</span><span class="meta-detail">{{ customer?.phone||order.customerPhone||'No contact details' }}</span></div><div class="order-meta-cell"><span class="meta-label">Created</span><span class="meta-value">{{ formatDateTime(order.createdAt) }}</span><span class="meta-detail">Jalali presentation</span></div><div class="order-meta-cell"><span class="meta-label">Promised date</span><JalaliDatePicker v-model="promisedAt" placeholder="Set promised date"/></div><div class="order-meta-cell"><span class="meta-label">Priority</span><span class="select-control"><select v-model="priority" aria-label="Priority"><option>Urgent</option><option>High</option><option>Normal</option><option>Low</option></select><ChevronDown class="select-chevron" :size="14"/></span></div><div class="order-meta-statuses"><span class="meta-label">Order states</span><div class="status-axis-list"><StatusBadge :label="order.commercialStatus" :tone="tone(order.commercialStatus)"/><span class="select-control"><select :value="order.fulfillmentStatus" aria-label="Fulfillment status" @change="changeFulfillment"><option>Pending</option><option>In Production</option><option>Ready</option><option>Delivered</option></select><ChevronDown class="select-chevron" :size="14"/></span><StatusBadge :label="order.paymentStatus" :tone="tone(order.paymentStatus)"/></div></div></section><WorkspaceTabs :tabs="tabs" :active-tab="tab" @update:active-tab="tab=$event"/></WorkspaceStickyStack>
<section v-if="tab==='Overview'" class="order-content-grid"><section class="panel order-details-panel"><header class="panel-header"><div><h2 class="panel-title">Order details</h2><p class="panel-subtitle">Customer and delivery context</p></div></header><div class="order-form"><label>Customer<span class="select-control"><select v-model="customerId"><option value="">Walk-in customer</option><option v-for="c in customers.filter((x:any)=>x.active||x.id===customerId)" :key="c.id" :value="c.id">{{ c.name }}</option></select><ChevronDown class="select-chevron" :size="14"/></span></label><label>Notes<textarea v-model="notes" rows="5" placeholder="Order notes"/></label></div><button class="button button-primary" :disabled="saving" @click="saveMetadata">Save details</button></section><section class="panel order-summary-panel"><header class="panel-header"><h2 class="panel-title">Order summary</h2></header><div class="summary-metrics"><span>Subtotal<strong>{{ money(order.subtotalRial) }}</strong></span><span>Discount<strong>{{ money(order.discountRial) }}</strong></span><span>Total<strong>{{ money(order.totalRial) }}</strong></span><span>Estimated cost<strong>{{ money(order.estimatedCostRial) }}</strong></span></div><label class="discount-field">Order discount<input :value="discountText" inputmode="decimal" @input="discountText=($event.target as HTMLInputElement).value" @blur="discountText=formatMoneyInput(parseMoneyInput(discountText,props.currencyUnit)||0,props.currencyUnit)"/><button class="button button-secondary" @click="updateDiscount">Apply</button></label></section></section>
<section v-else-if="tab==='Items'" class="order-items-area"><div v-if="!editorOpen" class="panel"><header class="panel-header"><div><h2 class="panel-title">Configured items</h2><p class="panel-subtitle">Each item keeps its accepted service and pricing snapshot.</p></div><button class="button button-primary" @click="editorOpen=true"><Plus :size="15"/>Add service item</button></header><div v-if="!order.items.length" class="workspace-state">No items yet. Add the first configured service.</div><div v-for="item in [...order.items].sort((a,b)=>a.position-b.position)" :key="item.id" class="order-item-row"><div class="item-position">{{ item.position+1 }}</div><div class="item-copy"><strong>{{ item.serviceName }}</strong><span>{{ item.quantity }} {{ item.quantityUnit }}<template v-if="item.notes"> · {{ item.notes }}</template></span><small>Accepted snapshot · {{ snapshot(item,'resolvedParametersJson').length }} parameters · {{ snapshot(item,'costBreakdownJson').length }} cost lines</small></div><div class="item-prices"><span>Cost {{ money(item.estimatedCostRial) }}</span><strong>{{ money(item.sellingPriceRial) }}</strong></div><div class="item-actions"><button class="icon-button" aria-label="Move item up" @click="move(item,-1)"><ArrowUp :size="14"/></button><button class="icon-button" aria-label="Move item down" @click="move(item,1)"><ArrowDown :size="14"/></button><button class="icon-button" aria-label="Reconfigure item" @click="editingItem=item;editorOpen=true"><Pencil :size="14"/></button><button class="icon-button danger" aria-label="Remove item" @click="remove(item)"><Trash2 :size="14"/></button></div></div></div><OrderItemConfigurator v-else :services="services" :materials="materials" :currency-unit="currencyUnit" :initial="editingItem" @configured="configured" @cancel="editorOpen=false;editingItem=null"/></section>
<OrderInvoicePanel v-else-if="tab==='Invoices'" :order="order" :currency-unit="currencyUnit" @notify="emit('notify',$event)" @saved="emit('saved',$event)" /><DocumentMetadataPanel v-else-if="tab==='Files'" owner-type="order" :owner-id="order.id" :protected-context="order.commercialStatus !== 'Draft'" @notify="emit('notify',$event)" /><OrderProductionPanel v-else-if="tab==='Production'" :order="order" :currency-unit="currencyUnit" /><OrderPaymentsPanel v-else-if="tab==='Payments'" :order="order" :currency-unit="currencyUnit" @notify="emit('notify',$event)" @saved="emit('saved',$event)" /><section v-else class="panel workspace-state order-placeholder"><strong>{{ tab }}</strong><span>This workflow is intentionally reserved for a later milestone. Persisted order data remains unchanged.</span></section>
</div></template>
